// Read-only snapshot analysis. Does not attach to, query or control the client.
import fs from 'node:fs/promises';
import path from 'node:path';
import crypto from 'node:crypto';
const project=path.resolve(import.meta.dirname,'..'),name='native-manual-1793848496660';
const input=path.join(project,'reports',name+'.performance.jsonl'),engine=path.join(project,'reports',name+'.engine.log');
const bytes=await fs.readFile(input),engineBytes=await fs.readFile(engine);
if(bytes.length>16*1024*1024||engineBytes.length>8*1024*1024)throw Error('Analysis input exceeds bounded snapshot');
const hash=b=>crypto.createHash('sha256').update(b).digest('hex');
const text=bytes.toString('utf8'),parts=text.split('\n'),rows=[];let incomplete=0;
for(let i=0;i<parts.length;i++){if(!parts[i].trim())continue;try{rows.push(JSON.parse(parts[i]));}catch(error){if(i!==parts.length-1)throw error;incomplete++;}}
const metric=(row,key)=>row?.frame_profile?.metrics?.[key]??null;
const keys=['wall_ms','process_ms','physics_ms','callback_envelope_ms','accounted_callback_ms','unattributed_callback_ms','callback_overlap_ms','outside_callback_ms','postdraw_render_frame_wall_ms','render_cpu_ms','render_gpu_ms','render_setup_cpu_ms','postdraw_render_boundary_setup_cpu_ms','profiler_collect_ms','profiler_record_ms','draws','triangles','nodes','objects','orphan_nodes','memory_static_bytes','video_memory_bytes','texture_memory_bytes','buffer_memory_bytes'];
const compact=m=>m?{mean:m.mean,p95:m.p95,max:m.max,samples:m.samples,active_samples:m.active_samples}:null;
function sample(row){
 const metrics=row.frame_profile?.metrics??{},callbacks=Object.entries(metrics).filter(([key])=>row.frame_profile?.callback_owners?.includes(key)).map(([key,value])=>({key,...compact(value)})).sort((a,b)=>b.mean-a.mean);
 const cpu=Object.entries(metrics).filter(([key])=>!key.startsWith('callback_')&&!/(?:^|_)count(?:_|$)/.test(key)&&!/(?:memory|nodes|objects|resources|draws|triangles|pipeline|vertices|batches|bytes|registered|frames)/.test(key)&&!keys.includes(key)).map(([key,value])=>({key,...compact(value)})).sort((a,b)=>b.mean-a.mean);
 return{at:row.at,capturedAtMs:row.frame_profile?.captured_at_ms,connection:row.connection,generation:row.generation,areaId:row.areaId,fps:row.fps,ready:row.ready,pendingBatches:row.pending_batches,entities:row.entities,desired:row.desired,tiles:row.tiles,windowFrames:row.frame_profile?.frames,core:Object.fromEntries(keys.map(key=>[key,compact(metric(row,key))])),callbacks:callbacks.slice(0,12),childrenInclusiveNotAdditive:cpu.slice(0,25),worstFrame:row.frame_profile?.worst_frame,renderThread:row.frame_profile?.render_thread,particles:row.particles,particleNative:row.shared_particles?.native,particleRenderer:row.shared_particles?.renderer,host:row.protocol_host,ui:row.ui_startup?{elapsed_ms:row.ui_startup.elapsed_ms,hud_presented_ms:row.ui_startup.hud_presented_ms,all_rules_ready_ms:row.ui_startup.all_rules_ready_ms,tables_ready:row.ui_startup.tables_ready,pending_custom_text:row.ui_startup.pending_custom_text}:null,protocolOutput:row.protocol_output};
}
const profiled=rows.filter(row=>row.frame_profile?.frames>0),latest=profiled.at(-1);
const loading=profiled.filter(row=>!row.ready||row.pending_batches>0||row.entities<row.desired);
const steady=profiled.filter(row=>row.ready&&row.pending_batches===0&&row.entities===row.desired);
const maxBy=(list,key)=>list.reduce((best,row)=>!best||(metric(row,key)?.max??-1)>(metric(best,key)?.max??-1)?row:best,null);
const summary=list=>({samples:list.length,firstAt:list[0]?.at??null,lastAt:list.at(-1)?.at??null,fpsRange:list.length?[Math.min(...list.map(r=>r.fps)),Math.max(...list.map(r=>r.fps))]:null,wallWindowMeanRange:list.length?[Math.min(...list.map(r=>metric(r,'wall_ms')?.mean??Infinity)),Math.max(...list.map(r=>metric(r,'wall_ms')?.mean??0))]:null,areas:[...new Set(list.map(r=>r.areaId))]});
const lines=engineBytes.toString('utf8').split(/\r?\n/),errors=lines.filter(line=>/^(?:ERROR:|SCRIPT ERROR:|WARNING:)/.test(line));
const groups=new Map();for(const line of errors){const key=line.replace(/0x[0-9a-f]+/gi,'<address>').slice(0,240);groups.set(key,(groups.get(key)??0)+1);}
const report={schema:1,kind:'read-only-active-session-frame-profile-snapshot',source:{path:path.relative(project,input),bytes:bytes.length,sha256:hash(bytes),completeRows:rows.length,incompleteTrailingRowsIgnored:incomplete,enginePath:path.relative(project,engine),engineBytes:engineBytes.length,engineSha256:hash(engineBytes)},timingScope:'Each observation summarizes a rolling completed window (normally240 frames). Windows overlap; their means/quantiles are not independent raw frames. Top callbacks may be compared as instrumented owners; child spans are inclusive and must not be summed. Outside-callback/render wall intervals are not GPU timings. Detailed profiling itself adds overhead.',observations:{all:summary(profiled),loading:summary(loading),steady:summary(steady)},latest:latest?sample(latest):null,latestSteady:steady.length?sample(steady.at(-1)):null,worstLoadingWall:loading.length?sample(maxBy(loading,'wall_ms')):null,worstLoadingRoot:loading.length?sample(maxBy(loading,'callback_root')):null,engine:{diagnosticLines:errors.length,top:Array.from(groups,([message,count])=>({message,count})).sort((a,b)=>b.count-a.count).slice(0,10)},limits:['This is a finite captured prefix of an actively growing log, not final session evidence.','No new instrumentation, GPU query, test, engine, socket or process control was performed.','Render counters are proxies/asynchronous; no measured GPU bottleneck or clean FPS benchmark is claimed.']};
const output=path.join(project,'reports',name+'-frame-analysis-v2.json');await fs.writeFile(output,JSON.stringify(report,null,2)+'\n',{flag:'wx'});
const brief=row=>row?{at:row.at,capturedAtMs:row.capturedAtMs,fps:row.fps,ready:row.ready,pending:row.pendingBatches,entities:row.entities,desired:row.desired,core:row.core,callbacks:row.callbacks,children:row.childrenInclusiveNotAdditive.slice(0,14),renderThread:row.renderThread,particles:row.particles,host:row.host}:null;
console.log(JSON.stringify({output,source:report.source,observations:report.observations,latest:brief(report.latest),engine:report.engine},null,2));
